import org.junit.Assert;
import org.junit.Test;
import org.jsoup.Connection;
import java.net.URL;
import java.io.UnsupportedEncodingException;

public class UrlBuilderTest {

    @Test
    public void UrlBuilderConstructorValidInputTest() {
        try {
            URL url = new URL("http://example.com");
            UrlBuilder urlBuilder = new UrlBuilder(url);
            Assert.assertNotNull(urlBuilder);
        } catch (Exception e) {
            Assert.fail();
        }
    }

    @Test(expected = UnsupportedEncodingException.class)
    public void appendKeyValEmptyStringTest() throws UnsupportedEncodingException {
        try {
            URL url = new URL("http://example.com");
            UrlBuilder urlBuilder = new UrlBuilder(url);
            Assert.assertNotNull(urlBuilder);
            urlBuilder.appendKeyVal(new Connection.KeyVal("", ""));
        } catch (Exception e) {
            Assert.fail();
        }
    }

    @Test
    public void appendKeyValValidInputTest() {
        try {
            URL url = new URL("http://example.com");
            UrlBuilder urlBuilder = new UrlBuilder(url);
            Assert.assertNotNull(urlBuilder);
            urlBuilder.appendKeyVal(new Connection.KeyVal("key", "value"));
        } catch (Exception e) {
            Assert.fail();
        }
    }

    @Test
    public void buildValidInputTest() {
        try {
            URL url = new URL("http://example.com");
            UrlBuilder urlBuilder = new UrlBuilder(url);
            Assert.assertNotNull(urlBuilder);
            URL resultUrl = urlBuilder.build();
            Assert.assertEquals(url, resultUrl);
        } catch (Exception e) {
            Assert.fail();
        }
    }

    @Test
    public void buildAfterAppendingKeyValTest() {
        try {
            URL url = new URL("http://example.com");
            UrlBuilder urlBuilder = new UrlBuilder(url);
            Assert.assertNotNull(urlBuilder);
            urlBuilder.appendKeyVal(new Connection.KeyVal("key", "value"));
            URL resultUrl = urlBuilder.build();
            Assert.assertNotEquals(url, resultUrl);
        } catch (Exception e) {
            Assert.fail();
        }
    }
}
